133	/// Find running `xray` process PIDs by scanning `/proc` directly — no
134	/// `pgrep`/`pkill` subprocess spawning (CLAUDE.md: no `Command::new(...)`
135	/// subprocesses in plugin/service code).
136	fn find_xray_pids() -> Vec<nix::unistd::Pid> {
137	    let mut pids = Vec::new();
138	    let Ok(entries) = std::fs::read_dir("/proc") else {
139	        return pids;
140	    };
141	    for entry in entries.flatten() {
142	        let Ok(pid) = entry.file_name().to_string_lossy().parse::<i32>() else {
143	            continue;
144	        };
145	        let comm_path = entry.path().join("comm");
146	        if let Ok(comm) = std::fs::read_to_string(&comm_path) {
147	            if comm.trim() == "xray" {
148	                pids.push(nix::unistd::Pid::from_raw(pid));
149	            }
150	        }
151	    }
152	    pids
153	}
