221	    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
222	        Ok(StateDiff {
223	            plugin: self.name().to_string(),
224	            actions: vec![],
225	            metadata: op_state::DiffMetadata {
226	                timestamp: std::time::SystemTime::now()
227	                    .duration_since(std::time::UNIX_EPOCH)?
228	                    .as_secs() as i64,
229	                current_hash: "".to_string(),
230	                desired_hash: "".to_string(),
231	            },
232	        })
233	    }
234	
235	    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
236	        // xray control point (the ONLY projectable tree: /org/opdbus/v1/plugins/xray).
237	        // Host-native lifecycle — no out-of-tree `opdbus.v1.Xray` daemon.
238	        let mut changes = Vec::new();
239	        let mut errors = Vec::new();
240	        let pids = find_xray_pids();
241	        if self.config.enabled {
242	            // Reload (SIGHUP) so a running xray re-reads its config; if none is
243	            // running, the container's own supervisor (systemd, inside the
244	            // `xray` container) is responsible for starting it.
245	            if pids.is_empty() {
246	                changes.push("xray not running; supervisor starts it".to_string());
247	            } else {
248	                for pid in pids {
249	                    match nix::sys::signal::kill(pid, nix::sys::signal::Signal::SIGHUP) {
250	                        Ok(()) => changes.push(format!("xray reloaded (SIGHUP, pid {pid})")),
251	                        Err(e) => errors.push(format!("xray reload failed (pid {pid}): {e}")),
252	                    }
253	                }
254	            }
255	        } else if pids.is_empty() {
256	            changes.push("xray already stopped".to_string());
257	        } else {
258	            for pid in pids {
259	                match nix::sys::signal::kill(pid, nix::sys::signal::Signal::SIGTERM) {
260	                    Ok(()) => changes.push(format!("xray stopped (pid {pid})")),
261	                    Err(e) => errors.push(format!("xray stop failed (pid {pid}): {e}")),
262	                }
263	            }
264	        }
265	        Ok(ApplyResult {
266	            success: errors.is_empty(),
267	            changes_applied: changes,
268	            errors,
269	            checkpoint: None,
270	        })
271	    }
