    #[schemars(extend("x-oscal-subid" = "mut.software.antigravity-chat.config-headless@v1"))]
    pub headless: bool,
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.software.antigravity-chat.config-display-service@v1"))]
