1	//! Compact MCP state plugin
2	//!
3	//! Tracks and manages the op-mcp-server: mode, transport bind addresses,
4	//! WireGuard identity, and tool registry.  Publishes live state to D-Bus
5	//! under `/opdbus/v1/plugins/compact_mcp` so that
6	//! `register_plugin_projection_tools` can expose it as MCP tools.
7	
8	use anyhow::{Context, Result};
9	use async_trait::async_trait;
10	use op_state::{
11	    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
12	};
13	use op_state_store::PluginSchema;
14	use serde::{Deserialize, Serialize};
15	use simd_json::{prelude::*, OwnedValue as Value};
16	
17	const RUNIT_SERVICE_PATH: &str = "/etc/runit/sv/op-mcp-compact";
18	const RUNIT_ACTIVE_PATH: &str = "/etc/runit/runsvdir/default/op-mcp-compact";
19	const ENV_DIR: &str = "/etc/runit/sv/op-mcp-compact/env";
20	const DEFAULT_MODE: &str = "compact";
21	const DEFAULT_HTTP: &str = "127.0.0.1:11436";
22	const DEFAULT_WG: &str = "netmaker";
23	
24	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
25	pub struct CompactMcpConfig {
26	    /// Server mode: compact | full | agents
27	    #[serde(default = "default_mode")]
28	    pub mode: String,
29	    /// HTTP/SSE bind address (when not using stdio)
30	    #[serde(default = "default_http")]
31	    pub http: Option<String>,
32	    /// WebSocket bind address
33	    #[serde(default)]
34	    pub ws: Option<String>,
35	    /// WireGuard interface for identity
36	    #[serde(default = "default_wg")]
37	    pub wg_interface: String,
38	    /// Run stdio transport (not used for runit daemon deployment)
39	    #[serde(default = "default_false")]
40	    pub stdio: bool,
41	    /// Log level
42	    #[serde(default = "default_log_level")]
43	    pub log_level: String,
44	}
45	
46	fn default_mode() -> String {
47	    DEFAULT_MODE.into()
48	}
49	fn default_http() -> Option<String> {
50	    Some(DEFAULT_HTTP.into())
51	}
52	fn default_wg() -> String {
53	    DEFAULT_WG.into()
54	}
55	fn default_false() -> bool {
56	    false
57	}
58	fn default_true() -> bool {
59	    true
60	}
61	fn default_log_level() -> String {
62	    "info".into()
63	}
64	
65	impl Default for CompactMcpConfig {
66	    fn default() -> Self {
67	        Self {
68	            mode: default_mode(),
69	            http: default_http(),
70	            ws: None,
71	            wg_interface: default_wg(),
72	            stdio: false,
73	            log_level: default_log_level(),
74	        }
75	    }
76	}
