78	pub struct CompactMcpPlugin;
79	
80	impl CompactMcpPlugin {
81	    pub fn new() -> Self {
82	        Self
83	    }
84	
85	    fn read_env(key: &str) -> Option<String> {
86	        std::fs::read_to_string(format!("{ENV_DIR}/{key}"))
87	            .ok()
88	            .map(|s| s.trim().to_string())
89	            .filter(|s| !s.is_empty())
90	    }
91	
92	    fn current_config() -> CompactMcpConfig {
93	        CompactMcpConfig {
94	            mode: Self::read_env("OP_MCP_MODE").unwrap_or_else(default_mode),
95	            http: Self::read_env("OP_MCP_HTTP"),
96	            ws: Self::read_env("OP_MCP_WS"),
97	            wg_interface: Self::read_env("WG_INTERFACE").unwrap_or_else(default_wg),
98	            stdio: Self::read_env("OP_MCP_STDIO")
99	                .map(|v| v != "0")
100	                .unwrap_or(false),
101	            log_level: Self::read_env("OP_MCP_LOG_LEVEL").unwrap_or_else(default_log_level),
102	        }
103	    }
104	
105	    async fn write_env(key: &str, value: &str) -> Result<()> {
106	        tokio::fs::create_dir_all(ENV_DIR)
107	            .await
108	            .context("create compact_mcp env dir")?;
109	        tokio::fs::write(format!("{ENV_DIR}/{key}"), value)
110	            .await
111	            .with_context(|| format!("write env {key}"))?;
112	        Ok(())
113	    }
114	
115	    async fn reload_service() -> Result<()> {
116	        let status = tokio::process::Command::new("sv")
117	            .arg("restart")
118	            .arg(RUNIT_ACTIVE_PATH)
119	            .status()
120	            .await
121	            .context("sv restart op-mcp-compact")?;
122	        if status.success() {
123	            tracing::info!("Restarted op-mcp-compact through runit");
124	            Ok(())
125	        } else {
126	            anyhow::bail!("sv restart op-mcp-compact exited with {status}")
127	        }
128	    }
129	}
