137	#[async_trait]
138	impl StatePlugin for CompactMcpPlugin {
139	    fn name(&self) -> &str {
140	        "compact_mcp"
141	    }
142	    fn version(&self) -> &str {
143	        "1.0.0"
144	    }
145	
146	    fn schema(&self) -> Option<PluginSchema> {
147	        let mut schema = compact_mcp_schema();
148	        super::common::oscal::ensure_category_metadata_fields(&mut schema);
149	        Some(schema)
150	    }
151	
152	    fn is_available(&self) -> bool {
153	        std::path::Path::new(RUNIT_SERVICE_PATH).exists()
154	    }
155	
156	    fn unavailable_reason(&self) -> String {
157	        format!("op-mcp-compact runit service definition not found at {RUNIT_SERVICE_PATH}")
158	    }
159	
160	    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
161	        let cur: CompactMcpConfig = simd_json::serde::from_owned_value(current.clone())?;
162	        let des: CompactMcpConfig = simd_json::serde::from_owned_value(desired.clone())?;
163	
164	        let mut actions = Vec::new();
165	        macro_rules! diff {
166	            ($field:ident, $key:expr) => {
167	                if cur.$field != des.$field {
168	                    actions.push(StateAction::Modify {
169	                        resource: $key.into(),
170	                        changes: simd_json::serde::to_owned_value(&des.$field)?,
171	                    });
172	                }
173	            };
174	        }
175	        diff!(mode, "mode");
176	        diff!(http, "http");
177	        diff!(ws, "ws");
178	        diff!(wg_interface, "wg_interface");
179	        diff!(stdio, "stdio");
180	        diff!(log_level, "log_level");
181	
182	        Ok(StateDiff {
183	            plugin: self.name().into(),
184	            actions,
185	            metadata: DiffMetadata {
186	                timestamp: chrono::Utc::now().timestamp(),
187	                current_hash: format!("{:x}", md5::compute(simd_json::to_string(current)?)),
188	                desired_hash: format!("{:x}", md5::compute(simd_json::to_string(desired)?)),
189	            },
190	        })
191	    }
192	
193	    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
194	        let mut changes = Vec::new();
195	        let mut errors = Vec::new();
196	        let mut needs_reload = false;
197	
198	        for action in &diff.actions {
199	            if let StateAction::Modify {
200	                resource,
201	                changes: val,
202	            } = action
203	            {
204	                let result: Result<()> = match resource.as_str() {
205	                    "mode" => {
206	                        if let Some(s) = val.as_str() {
207	                            Self::write_env("OP_MCP_MODE", s).await?;
208	                            needs_reload = true;
209	                            Ok(())
210	                        } else {
211	                            Err(anyhow::anyhow!("mode must be a string"))
212	                        }
213	                    }
214	                    "http" => {
215	                        match val.as_str() {
216	                            Some(s) => {
217	                                Self::write_env("OP_MCP_HTTP", s).await?;
218	                            }
219	                            None => {
220	                                let _ =
221	                                    tokio::fs::remove_file(format!("{ENV_DIR}/OP_MCP_HTTP")).await;
222	                            }
223	                        }
224	                        needs_reload = true;
225	                        Ok(())
226	                    }
227	                    "ws" => {
228	                        match val.as_str() {
229	                            Some(s) => {
230	                                Self::write_env("OP_MCP_WS", s).await?;
231	                            }
232	                            None => {
233	                                let _ =
234	                                    tokio::fs::remove_file(format!("{ENV_DIR}/OP_MCP_WS")).await;
235	                            }
236	                        }
237	                        needs_reload = true;
238	                        Ok(())
239	                    }
240	                    "wg_interface" => {
241	                        if let Some(s) = val.as_str() {
242	                            Self::write_env("WG_INTERFACE", s).await?;
243	                            needs_reload = true;
244	                            Ok(())
245	                        } else {
246	                            Err(anyhow::anyhow!("wg_interface must be a string"))
247	                        }
248	                    }
249	                    "stdio" => {
250	                        let v = if val.as_bool() == Some(false) {
251	                            "0"
252	                        } else {
253	                            "1"
254	                        };
255	                        Self::write_env("OP_MCP_STDIO", v).await?;
256	                        needs_reload = true;
257	                        Ok(())
258	                    }
259	                    "log_level" => {
260	                        if let Some(s) = val.as_str() {
261	                            Self::write_env("OP_MCP_LOG_LEVEL", s).await?;
262	                            needs_reload = true;
263	                            Ok(())
264	                        } else {
265	                            Err(anyhow::anyhow!("log_level must be a string"))
266	                        }
267	                    }
268	                    other => Err(anyhow::anyhow!("unknown compact_mcp field: {other}")),
269	                };
270	
271	                match result {
272	                    Ok(()) => changes.push(format!("compact_mcp.{resource} updated")),
273	                    Err(e) => errors.push(format!("compact_mcp.{resource}: {e}")),
274	                }
275	            }
276	        }
277	
278	        if needs_reload && errors.is_empty() {
279	            if let Err(e) = Self::reload_service().await {
280	                tracing::warn!("compact_mcp reload: {e}");
281	            }
282	        }
283	
284	        Ok(ApplyResult {
285	            success: errors.is_empty(),
286	            changes_applied: changes,
287	            errors,
288	            checkpoint: None,
289	        })
290	    }
291	
292	    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
293	        Ok(true)
294	    }
295	
296	    async fn create_checkpoint(&self) -> Result<Checkpoint> {
297	        let current = simd_json::json!(null);
298	        Ok(Checkpoint {
299	            id: format!("compact_mcp-{}", chrono::Utc::now().timestamp()),
300	            plugin: self.name().into(),
301	            timestamp: chrono::Utc::now().timestamp(),
302	            state_snapshot: current,
303	            backend_checkpoint: None,
304	        })
305	    }
306	
307	    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
308	        let old: CompactMcpConfig =
309	            simd_json::serde::from_owned_value(checkpoint.state_snapshot.clone())?;
310	        let desired = simd_json::serde::to_owned_value(&old)?;
311	        let current = simd_json::json!(null);
312	        let diff = self.calculate_diff(&current, &desired).await?;
313	        self.apply_state(&diff).await?;
314	        Ok(())
315	    }
316	
317	    fn capabilities(&self) -> PluginCapabilities {
318	        PluginCapabilities {
319	            supports_rollback: true,
320	            supports_checkpoints: true,
321	            supports_verification: true,
322	            atomic_operations: false,
323	        }
324	    }
325	}
