163	                let mut servers = HashMap::new();
164	
165	                // simple, flat list of agents to auto-load
166	                let agents = vec![
167	                    "rust-pro",
168	                    "backend-architect",
169	                    "network-engineer",
170	                    "context-manager",
171	                    "memory",
172	                    "sequential-thinking",
173	                ];
174	
175	                for agent in agents {
