213	    /// Apply server configuration changes
214	    async fn apply_server_config(&self, server_name: &str, config: &McpServerConfig) -> Result<()> {
215	        // Create execution job for state tracking
216	        let job = ExecutionJob {
217	            id: Uuid::new_v4(),
218	            tool_name: format!("mcp:configure_server:{}", server_name),
219	            arguments: simd_json::serde::to_owned_value(config)?,
220	            status: ExecutionStatus::Running,
221	            created_at: chrono::Utc::now(),
222	            updated_at: chrono::Utc::now(),
223	            result: None,
224	        };
225	
226	        // Save job to state store
227	        self.state_store.save_job(&job).await?;
228	
229	        // Load current config
230	        let mut current = self.load_config().await.unwrap_or_else(|_| McpConfig {
231	            servers: Some(HashMap::new()),
232	            tool_groups: None,
233	            compact_mode: None,
234	        });
235	
236	        // Update server config
237	        let servers = current.servers.get_or_insert_with(HashMap::new);
238	        servers.insert(server_name.to_string(), config.clone());
239	
240	        // Save updated config
241	        self.save_config(&current).await?;
242	
243	        // Update job status
244	        let mut job = job;
245	        job.status = ExecutionStatus::Completed;
246	        job.updated_at = chrono::Utc::now();
247	        job.result = Some(op_state_store::ExecutionResult {
248	            success: true,
249	            output: Some(simd_json::serde::to_owned_value(
250	                "Server configured successfully",
251	            )?),
252	            error: None,
253	        });
254	        self.state_store.update_job(&job).await?;
255	
256	        log::info!("Configured MCP server: {}", server_name);
257	        Ok(())
258	    }
