392	    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
393	        let current_config: McpConfig = simd_json::serde::from_owned_value(current.clone())?;
394	        let desired_config: McpConfig = simd_json::serde::from_owned_value(desired.clone())?;
395	
396	        let mut actions = Vec::new();
397	
398	        // Check server changes
399	        if let Some(desired_servers) = &desired_config.servers {
400	            for (server_name, desired_server) in desired_servers {
401	                let current_server = current_config
402	                    .servers
403	                    .as_ref()
404	                    .and_then(|s| s.get(server_name));
405	
406	                if current_server != Some(desired_server) {
407	                    actions.push(StateAction::Modify {
408	                        resource: format!("server:{}", server_name),
409	                        changes: simd_json::serde::to_owned_value(desired_server)?,
410	                    });
411	                }
412	            }
413	        }
414	
415	        // Check tool groups changes
416	        if current_config.tool_groups != desired_config.tool_groups {
417	            if let Some(ref desired_groups) = desired_config.tool_groups {
418	                actions.push(StateAction::Modify {
419	                    resource: "tool_groups".to_string(),
420	                    changes: simd_json::serde::to_owned_value(desired_groups)?,
421	                });
422	            }
423	        }
424	
425	        // Check compact mode changes
426	        if current_config.compact_mode != desired_config.compact_mode {
427	            if let Some(ref desired_compact) = desired_config.compact_mode {
428	                actions.push(StateAction::Modify {
429	                    resource: "compact_mode".to_string(),
430	                    changes: simd_json::serde::to_owned_value(desired_compact)?,
431	                });
432	            }
433	        }
434	
435	        Ok(StateDiff {
436	            plugin: self.name().to_string(),
437	            actions,
438	            metadata: DiffMetadata {
439	                timestamp: chrono::Utc::now().timestamp(),
440	                current_hash: format!("{:x}", md5::compute(simd_json::to_string(current)?)),
441	                desired_hash: format!("{:x}", md5::compute(simd_json::to_string(desired)?)),
442	            },
443	        })
444	    }
445	
446	    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
447	        let mut changes_applied = Vec::new();
448	        let mut errors = Vec::new();
449	
450	        for action in &diff.actions {
451	            if let StateAction::Modify { resource, changes } = action {
452	                let result = if let Some(server_name) = resource.strip_prefix("server:") {
453	                    let server_config: McpServerConfig =
454	                        simd_json::serde::from_owned_value(changes.clone())?;
455	                    self.apply_server_config(server_name, &server_config).await
456	                } else if resource == "tool_groups" {
457	                    let groups_config: ToolGroupsConfig =
458	                        simd_json::serde::from_owned_value(changes.clone())?;
459	                    self.apply_tool_groups_config(&groups_config).await
460	                } else if resource == "compact_mode" {
461	                    // Compact mode changes don't require action - just config update
462	                    Ok(())
463	                } else {
464	                    Err(anyhow::anyhow!("Unknown resource: {}", resource))
465	                };
466	
467	                match result {
468	                    Ok(_) => {
469	                        changes_applied.push(format!("Applied MCP config for: {}", resource));
470	                    }
471	                    Err(e) => {
472	                        errors.push(format!("Failed to apply config for {}: {}", resource, e));
473	                    }
474	                }
475	            }
476	        }
477	
478	        Ok(ApplyResult {
479	            success: errors.is_empty(),
480	            changes_applied,
481	            errors,
482	            checkpoint: None,
483	        })
484	    }
485	
486	    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
487	        Ok(true)
488	    }
489	
490	    async fn create_checkpoint(&self) -> Result<Checkpoint> {
491	        let current = simd_json::json!(null);
492	        Ok(Checkpoint {
493	            id: format!("mcp-{}", chrono::Utc::now().timestamp()),
494	            plugin: self.name().to_string(),
495	            timestamp: chrono::Utc::now().timestamp(),
496	            state_snapshot: current,
497	            backend_checkpoint: None,
498	        })
499	    }
500	
501	    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
502	        let old_config: McpConfig =
503	            simd_json::serde::from_owned_value(checkpoint.state_snapshot.clone())?;
504	        self.save_config(&old_config).await?;
505	        log::info!("Rolled back MCP config to checkpoint: {}", checkpoint.id);
506	        Ok(())
507	    }
508	
509	    fn capabilities(&self) -> PluginCapabilities {
510	        PluginCapabilities {
511	            supports_rollback: true,
512	            supports_checkpoints: true,
513	            supports_verification: true,
514	            atomic_operations: false, // File writes are not atomic
515	        }
516	    }
517	}
