545	            collect_subids(items, out);
546	        }
547	        if let Some(alternatives) = node
548	            .get("anyOf")
549	            .or_else(|| node.get("oneOf"))
550	            .and_then(JVal::as_array)
551	        {
552	            for v in alternatives {
