50	    pub fn new(store_path: impl Into<PathBuf>) -> Self {
51	        Self {
52	            store_path: store_path.into(),
53	        }
54	    }
55	
56	    async fn load_store(&self) -> Result<PrivacyRoutesState> {
57	        match tokio::fs::read_to_string(&self.store_path).await {
58	            Ok(content) => {
59	                let mut state: PrivacyRoutesState =
60	                    serde_json::from_str(&content).context("invalid privacy route store")?;
61	                state.routes.sort_by(|a, b| a.route_id.cmp(&b.route_id));
62	                Ok(state)
63	            }
64	            Err(_) => Ok(PrivacyRoutesState { routes: Vec::new() }),
65	        }
66	    }
