68	    async fn save_store(&self, state: &PrivacyRoutesState) -> Result<()> {
69	        if let Some(parent) = self.store_path.parent() {
70	            tokio::fs::create_dir_all(parent)
71	                .await
72	                .context("failed to create privacy route directory")?;
73	        }
74	
75	        let content = simd_json::to_string_pretty(state).context("serialize privacy routes")?;
76	        tokio::fs::write(&self.store_path, content)
77	            .await
78	            .context("write privacy routes")?;
79	        Ok(())
80	    }
