97	    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
98	        let current_state: PrivacyRoutesState = simd_json::serde::from_owned_value(current.clone())
99	            .context("deserialize current privacy routes")?;
100	        let desired_state: PrivacyRoutesState = simd_json::serde::from_owned_value(desired.clone())
101	            .context("deserialize desired privacy routes")?;
102	
103	        let current_by_id: HashMap<&str, &PrivacyRoute> = current_state
104	            .routes
105	            .iter()
106	            .map(|route| (route.route_id.as_str(), route))
107	            .collect();
108	        let desired_by_id: HashMap<&str, &PrivacyRoute> = desired_state
109	            .routes
110	            .iter()
111	            .map(|route| (route.route_id.as_str(), route))
112	            .collect();
113	
114	        let mut actions = Vec::new();
115	
116	        for desired_route in &desired_state.routes {
117	            match current_by_id.get(desired_route.route_id.as_str()) {
118	                Some(current_route) if *current_route == desired_route => {}
119	                Some(_) => actions.push(StateAction::Modify {
120	                    resource: desired_route.route_id.clone(),
121	                    changes: simd_json::serde::to_owned_value(desired_route.clone())
122	                        .context("serialize desired privacy route modify")?,
123	                }),
124	                None => actions.push(StateAction::Create {
125	                    resource: desired_route.route_id.clone(),
126	                    config: simd_json::serde::to_owned_value(desired_route.clone())
127	                        .context("serialize desired privacy route create")?,
128	                }),
129	            }
130	        }
131	
132	        for current_route in &current_state.routes {
133	            if !desired_by_id.contains_key(current_route.route_id.as_str()) {
134	                actions.push(StateAction::Delete {
135	                    resource: current_route.route_id.clone(),
136	                });
137	            }
138	        }
139	
140	        Ok(StateDiff {
141	            plugin: self.name().to_string(),
142	            actions,
143	            metadata: DiffMetadata {
144	                timestamp: chrono::Utc::now().timestamp(),
145	                current_hash: format!("{:x}", md5::compute(simd_json::to_string(current)?)),
146	                desired_hash: format!("{:x}", md5::compute(simd_json::to_string(desired)?)),
147	            },
148	        })
149	    }
150	
151	    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
152	        let mut state = self.load_store().await?;
153	        let mut routes_by_id: HashMap<String, PrivacyRoute> = state
154	            .routes
155	            .drain(..)
156	            .map(|route| (route.route_id.clone(), route))
157	            .collect();
158	
159	        let mut changes_applied = Vec::new();
160	        let mut errors = Vec::new();
161	
162	        for action in &diff.actions {
163	            match action {
164	                StateAction::Create { resource, config } => {
165	                    let route: PrivacyRoute = simd_json::serde::from_owned_value(config.clone())
166	                        .context("deserialize route create")?;
167	                    routes_by_id.insert(resource.clone(), route);
168	                    changes_applied.push(format!("created privacy route {}", resource));
